UPDATE purchase_requests
SET requested_supplier_id = #{requestedSupplierId},
    title = #{title},
    reason = #{reason},
    desired_delivery_date = #{desiredDeliveryDate},
    note = #{note},
    version = version + 1,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND applicant_id = #{applicantId}
  AND status = 'DRAFT'
  AND version = #{expectedVersion}

mapper.delete:
DELETE FROM purchase_requests
WHERE id = #{requestId}
  AND applicant_id = #{applicantId}
  AND status = 'DRAFT'
  AND version = #{version}

mapper.update:
UPDATE purchase_requests
SET status = 'CANCELED',
    version = version + 1,
    updated_at = #{updatedAt}
WHERE id = #{requestId}
  AND applicant_id = #{applicantId}
  AND status = 'SUBMITTED'
  AND version = #{version}
